changeSet.sql:
SET @current_company := NULL;
SET @row_number := 1000;

UPDATE section s
    JOIN (
    SELECT id,
    company_id,
    @row_number := IF(@current_company = company_id, @row_number + 1, 1000) AS new_identifier,
    @current_company := company_id
    FROM section
    ORDER BY company_id, id
    ) AS sub
ON s.id = sub.id
    SET s.identifier = sub.new_identifier;
